def max_path_length(v1, v2, t, d):
    def can_achieve_length(length):
        speed = v1
        for _ in range(t - 1):
            if speed + d < v2:
                speed = min(speed + d, v2)
            else:
                speed = max(speed - d, v2)
            if speed * t > length:
                return False
        return speed == v2 and speed * t <= length

    left, right = 0, v1 * t
    while left < right:
        mid = (left + right + 1) // 2
        if can_achieve_length(mid):
            left = mid
        else:
            right = mid - 1
    return left

