def max_path_length(v1, v2, t, d):
    total_distance = 0
    current_speed = v1

    for second in range(t):
        if second == t - 1:
            total_distance += current_speed
        else:
            if current_speed < v2:
                next_speed = min(current_speed + d, v2)
            else:
                next_speed = max(current_speed - d, v2)

            total_distance += current_speed
            current_speed = next_speed

    return total_distance

